const svg=$('#posets-svg'), out=$('#posets-out');
const modeSl=$('#posets-mode'), modeL=$('#posets-mode-lbl'), clearBtn=$('#posets-clear');
const W=600,H=360;
// divisor lattice of 30 ~ B_3 of {2,3,5}; nodes laid out by number of prime factors (rank)
const nodes=[
  {n:1, rank:0, x:300},
  {n:2, rank:1, x:150}, {n:3, rank:1, x:300}, {n:5, rank:1, x:450},
  {n:6, rank:2, x:150}, {n:10, rank:2, x:300}, {n:15, rank:2, x:450},
  {n:30, rank:3, x:300}
];
const ys={0:320,1:235,2:130,3:45};
for(const v of nodes) v.y=ys[v.rank];
const byN={}; for(const v of nodes) byN[v.n]=v;
function divides(a,b){ return b%a===0; }
// covering edges: a covers b when a|b, a!=b, no c strictly between
const covers=[];
for(const a of nodes) for(const b of nodes){
  if(a.n!==b.n && divides(a.n,b.n)){
    let mid=false;
    for(const c of nodes) if(c.n!==a.n && c.n!==b.n && divides(a.n,c.n) && divides(c.n,b.n)) mid=true;
    if(!mid) covers.push([a.n,b.n]);
  }
}
let sel=[]; // up to two selected n-values
function comparable(a,b){ return divides(a,b) || divides(b,a); }
// maximal chain through one node: greedily extend down then up
function chainThrough(n){
  let chain=[n];
  let cur=n;
  while(true){ const below=nodes.filter(v=>divides(v.n,cur)&&v.n!==cur).sort((p,q)=>q.n-p.n); let nxt=null; for(const v of below){ if(covers.some(e=>e[0]===v.n&&e[1]===cur)){nxt=v.n;break;} } if(nxt===null) break; chain.unshift(nxt); cur=nxt; }
  cur=n;
  while(true){ const above=nodes.filter(v=>divides(cur,v.n)&&v.n!==cur).sort((p,q)=>p.n-q.n); let nxt=null; for(const v of above){ if(covers.some(e=>e[0]===cur&&e[1]===v.n)){nxt=v.n;break;} } if(nxt===null) break; chain.push(nxt); cur=nxt; }
  return chain;
}
const widestAntichain=[6,10,15]; // the rank-2 (and rank-1) levels have width 3
function render(){
  const mode=+modeSl.value;
  modeL.textContent = mode===0?'comparability (click 2 nodes)' : mode===1?'maximal chain (click 1 node)' : 'largest antichain';
  svg.innerHTML='';
  // highlighted edge/element sets
  let hiNodes=new Set(), hiEdges=new Set();
  let msg='';
  if(mode===0){
    sel.forEach(n=>hiNodes.add(n));
    if(sel.length===2){ msg = sel[0]+' and '+sel[1]+' are '+(comparable(sel[0],sel[1])?'COMPARABLE ('+(divides(sel[0],sel[1])?sel[0]+' | '+sel[1]:sel[1]+' | '+sel[0])+')':'INCOMPARABLE (neither divides the other)'); }
    else msg='click two nodes to test comparability';
  } else if(mode===1){
    if(sel.length>=1){ const ch=chainThrough(sel[sel.length-1]); ch.forEach(n=>hiNodes.add(n)); for(let i=0;i+1<ch.length;i++) hiEdges.add(ch[i]+'-'+ch[i+1]); msg='maximal chain through '+sel[sel.length-1]+': '+ch.join(' | ')+'   (length '+ch.length+')'; }
    else msg='click a node to grow a maximal chain through it';
  } else {
    widestAntichain.forEach(n=>hiNodes.add(n)); msg='largest antichain: {'+widestAntichain.join(', ')+'} — three pairwise-incomparable divisors (width = 3)';
  }
  // draw edges
  for(const [a,b] of covers){ const va=byN[a], vb=byN[b]; const hi=hiEdges.has(a+'-'+b);
    svg.appendChild(SVG('line',{x1:va.x,y1:va.y,x2:vb.x,y2:vb.y,stroke: hi?'var(--yellow)':'var(--line)','stroke-width':hi?3.5:1.5,opacity:hi?1:0.7})); }
  // draw nodes
  for(const v of nodes){ const hi=hiNodes.has(v.n);
    drawNode(svg,v.x,v.y,v.n,{r:18, fill: hi?'var(--panel)':'var(--panel2)', stroke: hi?'var(--yellow)':'var(--violet)', fontSize:13}); }
  // height/width caption (viewport coords)
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent='divisor lattice of 30  ≅  Boolean lattice B₃    height = 4 (longest chain)    width = 3 (largest antichain)'; svg.appendChild(cap);
  out.textContent = msg;
}
svg.addEventListener('click',(ev)=>{
  const pt=svg.getBoundingClientRect(); const sx=W/pt.width, sy=H/pt.height;
  const mx=(ev.clientX-pt.left)*sx, my=(ev.clientY-pt.top)*sy;
  let best=null,bd=1e9; for(const v of nodes){ const dd=(v.x-mx)**2+(v.y-my)**2; if(dd<bd){bd=dd;best=v;} }
  if(best && bd<900){ const mode=+modeSl.value; if(mode===0){ sel.push(best.n); if(sel.length>2) sel=sel.slice(-2); } else { sel=[best.n]; } render(); }
});
modeSl.addEventListener('input',()=>{ sel=[]; render(); });
clearBtn.addEventListener('click',()=>{ sel=[]; render(); });
render();

const svg=$('#lattices-svg'), out=$('#lattices-out'), pick=$('#lattices-pick');
const clearBtn=$('#lattices-clear');
const W=600,H=360;
// each lattice: nodes {id,x,y,label}, leq(a,b) predicate via reachability on covers
const LAT={};
// divisor lattice of 30
LAT.div30={ name:'divisor lattice of 30 (≅ B₃)', distributive:true, modular:true,
  nodes:[{id:'1',x:300,y:320},{id:'2',x:150,y:225},{id:'3',x:300,y:225},{id:'5',x:450,y:225},{id:'6',x:150,y:120},{id:'10',x:300,y:120},{id:'15',x:450,y:120},{id:'30',x:300,y:35}],
  covers:[['1','2'],['1','3'],['1','5'],['2','6'],['2','10'],['3','6'],['3','15'],['5','10'],['5','15'],['6','30'],['10','30'],['15','30']] };
// Boolean B3 over {a,b,c}
LAT.b3={ name:'Boolean lattice B₃', distributive:true, modular:true,
  nodes:[{id:'∅',x:300,y:320},{id:'a',x:150,y:225},{id:'b',x:300,y:225},{id:'c',x:450,y:225},{id:'ab',x:150,y:120},{id:'ac',x:300,y:120},{id:'bc',x:450,y:120},{id:'abc',x:300,y:35}],
  covers:[['∅','a'],['∅','b'],['∅','c'],['a','ab'],['a','ac'],['b','ab'],['b','bc'],['c','ac'],['c','bc'],['ab','abc'],['ac','abc'],['bc','abc']] };
// diamond M3
LAT.m3={ name:'diamond M₃', distributive:false, modular:true,
  nodes:[{id:'0',x:300,y:300},{id:'a',x:160,y:180},{id:'b',x:300,y:180},{id:'c',x:440,y:180},{id:'1',x:300,y:60}],
  covers:[['0','a'],['0','b'],['0','c'],['a','1'],['b','1'],['c','1']] };
// pentagon N5
LAT.n5={ name:'pentagon N₅', distributive:false, modular:false,
  nodes:[{id:'0',x:300,y:310},{id:'a',x:170,y:200},{id:'b',x:170,y:90},{id:'c',x:430,y:200},{id:'1',x:300,y:35}],
  covers:[['0','a'],['a','b'],['b','1'],['0','c'],['c','1']] };
let cur='div30', sel=[];
function reach(L){ // transitive closure: leq[x][y]
  const ids=L.nodes.map(n=>n.id); const leq={}; ids.forEach(i=>{leq[i]={}; ids.forEach(j=>leq[i][j]=(i===j));});
  L.covers.forEach(([a,b])=>leq[a][b]=true);
  let changed=true; while(changed){ changed=false; for(const x of ids) for(const y of ids) if(leq[x][y]) for(const z of ids) if(leq[y][z]&&!leq[x][z]){leq[x][z]=true;changed=true;} }
  return leq;
}
function meet(L,leq,a,b){ // greatest lower bound
  const lower=L.nodes.map(n=>n.id).filter(z=>leq[z][a]&&leq[z][b]);
  return lower.find(z=>lower.every(w=>leq[w][z]));
}
function join(L,leq,a,b){ const upper=L.nodes.map(n=>n.id).filter(z=>leq[a][z]&&leq[b][z]);
  return upper.find(z=>upper.every(w=>leq[z][w])); }
function render(){
  const L=LAT[cur]; const leq=reach(L);
  svg.innerHTML='';
  let hi=new Set(sel), mEl=null, jEl=null;
  if(sel.length===2){ mEl=meet(L,leq,sel[0],sel[1]); jEl=join(L,leq,sel[0],sel[1]); if(mEl)hi.add(mEl); if(jEl)hi.add(jEl); }
  const byId={}; L.nodes.forEach(n=>byId[n.id]=n);
  for(const [a,b] of L.covers){ const va=byId[a],vb=byId[b];
    svg.appendChild(SVG('line',{x1:va.x,y1:va.y,x2:vb.x,y2:vb.y,stroke:'var(--line)','stroke-width':1.5,opacity:0.7})); }
  for(const n of L.nodes){ let fill='var(--panel2)', stroke='var(--violet)';
    if(n.id===mEl){ stroke='var(--cyan)'; fill='var(--panel)'; }
    else if(n.id===jEl){ stroke='var(--pink)'; fill='var(--panel)'; }
    else if(sel.includes(n.id)){ stroke='var(--yellow)'; fill='var(--panel)'; }
    drawNode(svg,n.x,n.y,n.id,{r:19,fill,stroke,fontSize:12}); }
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent=L.name+'    cyan = meet (∧)    pink = join (∨)'; svg.appendChild(cap);
  let msg;
  if(sel.length===2) msg=sel[0]+' ∧ '+sel[1]+' = '+mEl+'    (greatest lower bound)\n'+sel[0]+' ∨ '+sel[1]+' = '+jEl+'    (least upper bound)';
  else msg='click two elements to compute their meet and join';
  msg += '\nlattice is '+(L.distributive?'DISTRIBUTIVE (no M₃ and no N₅ sublattice)':'NOT distributive')+'; '+(L.modular?'MODULAR (no N₅ sublattice)':'NOT modular (contains N₅)');
  out.textContent=msg;
}
svg.addEventListener('click',(ev)=>{
  const L=LAT[cur]; const pt=svg.getBoundingClientRect(); const sx=W/pt.width, sy=H/pt.height;
  const mx=(ev.clientX-pt.left)*sx, my=(ev.clientY-pt.top)*sy;
  let best=null,bd=1e9; for(const n of L.nodes){ const dd=(n.x-mx)**2+(n.y-my)**2; if(dd<bd){bd=dd;best=n;} }
  if(best && bd<1100){ sel.push(best.id); if(sel.length>2) sel=sel.slice(-2); render(); }
});
pick.addEventListener('change',()=>{ cur=pick.value; sel=[]; render(); });
clearBtn.addEventListener('click',()=>{ sel=[]; render(); });
render();

// Height is the order: HIGHER on screen = GREATER element (ties by id).
// Edges are read as covering relations; the partial order is the
// reflexive-transitive closure. The widget checks Hasse validity
// (no transitive shortcut edges) and whether the poset is a lattice
// (every pair has a meet and a join), naming witnesses when it fails.
const MAXN=10;
function draw(g){
  while(G.firstChild) G.removeChild(G.firstChild);
  const byId={}; g.nodes.forEach(function(n){ byId[n.id]=n; });
  const ids=g.nodes.map(function(n){ return n.id; });
  if(g.n===0){ out.innerHTML='click empty space to add an element'; return; }
  if(g.n>MAXN){
    g.edges.forEach(function(e){ const a=byId[e.u], b=byId[e.v];
      G.appendChild(SVG('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:'var(--line)','stroke-width':2,'pointer-events':'none'})); });
    g.nodes.forEach(function(n){ plain(n); });
    out.innerHTML='more than '+MAXN+' elements \u2014 remove some'; return;
  }
  // covers: [smaller, larger] with larger = smaller y (higher on screen)
  const up={}; ids.forEach(function(i){ up[i]=[]; });
  const covers=g.edges.map(function(e){
    const a=byId[e.u], b=byId[e.v];
    return (a.y>b.y || (a.y===b.y && e.u<e.v)) ? [e.u,e.v] : [e.v,e.u];
  });
  covers.forEach(function(c){ up[c[0]].push(c[1]); });
  const leq={};
  ids.forEach(function(a){
    const s={}; s[a]=1; const st=[a];
    while(st.length){ const v=st.pop(); up[v].forEach(function(w){ if(!s[w]){ s[w]=1; st.push(w); } }); }
    leq[a]=s;
  });
  function le(a,b){ return !!leq[a][b]; }
  const redundant={};
  covers.forEach(function(c,i){
    if(ids.some(function(x){ return x!==c[0]&&x!==c[1]&&le(c[0],x)&&le(x,c[1]); })){
      const e=g.edges[i]; redundant[Math.min(e.u,e.v)+'-'+Math.max(e.u,e.v)]=1;
    }
  });
  function bound(a,b,downward){
    const B=ids.filter(function(c){ return downward ? (le(c,a)&&le(c,b)) : (le(a,c)&&le(b,c)); });
    const ext=B.filter(function(c){ return !B.some(function(d2){ return d2!==c&&(downward?le(c,d2):le(d2,c)); }); });
    return {ok: B.length>0 && ext.length===1, wit: ext, got: ext.length===1?ext[0]:null};
  }
  var fail=null;
  outer:
  for(var i=0;i<ids.length;i++){
    for(var j=i+1;j<ids.length;j++){
      const m=bound(ids[i],ids[j],true);
      if(!m.ok){ fail={pair:[ids[i],ids[j]], wit:m.wit, kind:'meet'}; break outer; }
      const J=bound(ids[i],ids[j],false);
      if(!J.ok){ fail={pair:[ids[i],ids[j]], wit:J.wit, kind:'join'}; break outer; }
    }
  }
  // paint
  g.edges.forEach(function(e){
    const a=byId[e.u], b=byId[e.v], k=Math.min(e.u,e.v)+'-'+Math.max(e.u,e.v);
    const at={x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:redundant[k]?'var(--pink)':'var(--line)','stroke-width':redundant[k]?3:2,'pointer-events':'none'};
    if(redundant[k]) at['stroke-dasharray']='5 4';
    G.appendChild(SVG('line',at));
  });
  const pairSet={}, witSet={};
  if(fail){ fail.pair.forEach(function(v){ pairSet[v]=1; }); fail.wit.forEach(function(v){ witSet[v]=1; }); }
  function plain(n){
    G.appendChild(SVG('circle',{cx:n.x,cy:n.y,r:g.R,fill:witSet[n.id]?'var(--pink)':'var(--cyan)','fill-opacity':0.85,
      stroke:pairSet[n.id]?'var(--yellow)':'var(--bg)','stroke-width':pairSet[n.id]?3.5:2}));
    const t=SVG('text',{x:n.x,y:n.y+4,'font-size':11,fill:'var(--bg)','text-anchor':'middle','font-weight':'bold','pointer-events':'none'});
    t.textContent=String(n.id); G.appendChild(t);
  }
  g.nodes.forEach(plain);
  const nRed=Object.keys(redundant).length;
  var msg='';
  if(nRed){ msg+='<span class="bad">'+nRed+' dashed edge'+(nRed===1?' is a':'s are')+' transitive shortcut'+(nRed===1?'':'s')+' \u2014 a Hasse diagram draws only covering relations</span> \u00b7 '; }
  if(!fail){
    msg+='<span class="ok">every pair has a meet and a join \u2014 this poset is a lattice</span>';
    const bot=ids.filter(function(a){ return ids.every(function(b){ return le(a,b); }); });
    const top=ids.filter(function(a){ return ids.every(function(b){ return le(b,a); }); });
    if(bot.length===1&&top.length===1) msg+=' \u00b7 bounded: \u22a5 = '+bot[0]+', \u22a4 = '+top[0];
  } else {
    msg+='<span class="bad">not a lattice:</span> '+fail.pair[0]+' and '+fail.pair[1]+' (yellow rings) have no '+fail.kind;
    if(fail.wit.length>1) msg+=' \u2014 their '+(fail.kind==='meet'?'maximal common lower':'minimal common upper')+' bounds {'+fail.wit.join(', ')+'} (pink) are incomparable';
    else msg+=' \u2014 they have no common '+(fail.kind==='meet'?'lower':'upper')+' bound at all';
  }
  out.innerHTML=msg;
}

const svg=$('#dilworth-svg'), out=$('#dilworth-out');
const viewSl=$('#dilworth-view'), viewL=$('#dilworth-view-lbl');
const W=600,H=340;
// divisor lattice of 12
const nodes=[{n:1,x:300,y:300},{n:2,x:200,y:210},{n:3,x:400,y:210},{n:4,x:200,y:120},{n:6,x:400,y:120},{n:12,x:300,y:35}];
const byN={}; nodes.forEach(v=>byN[v.n]=v);
function divides(a,b){ return b%a===0; }
const covers=[];
for(const a of nodes) for(const b of nodes) if(a.n!==b.n && divides(a.n,b.n)){ let mid=false; for(const c of nodes) if(c.n!==a.n&&c.n!==b.n&&divides(a.n,c.n)&&divides(c.n,b.n)) mid=true; if(!mid) covers.push([a.n,b.n]); }
const chainCover=[[1,2,4,12],[3,6]]; // width 2 -> 2 chains
const antichain=[4,6];                // width = 2
const longestChain=[1,2,4,12];        // height = 4
const rankLevels=[[1],[2,3],[4,6],[12]]; // 4 antichains (Mirsky)
const chainColors=['var(--cyan)','var(--pink)','var(--green)'];
const acColors=['var(--yellow)','var(--cyan)','var(--pink)','var(--green)'];
function render(){
  const view=+viewSl.value;
  viewL.textContent = view===0?'Dilworth: antichain vs chain cover':'Mirsky: longest chain vs antichain cover';
  svg.innerHTML='';
  for(const [a,b] of covers){ const va=byN[a],vb=byN[b]; svg.appendChild(SVG('line',{x1:va.x,y1:va.y,x2:vb.x,y2:vb.y,stroke:'var(--line)','stroke-width':1.5,opacity:0.6})); }
  let msg='';
  if(view===0){
    // color each node by which cover-chain it belongs to
    const colorOf={}; chainCover.forEach((ch,i)=>ch.forEach(n=>colorOf[n]=chainColors[i]));
    const acSet=new Set(antichain);
    for(const v of nodes){ const isAc=acSet.has(v.n);
      drawNode(svg,v.x,v.y,v.n,{r:18,fill: isAc?'var(--panel)':'var(--panel2)', stroke: colorOf[v.n]||'var(--violet)', fontSize:13}); }
    // ring the antichain elements
    for(const n of antichain){ const v=byN[n]; svg.appendChild(SVG('circle',{cx:v.x,cy:v.y,r:24,fill:'none',stroke:'var(--ink)','stroke-width':2,'stroke-dasharray':'4 3'})); }
    const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent='dashed ring = maximum antichain    node color = which cover-chain'; svg.appendChild(cap);
    msg='maximum antichain {'+antichain.join(', ')+'} has size 2 = WIDTH\n'+'minimum chain cover: {'+chainCover.map(c=>c.join('|')).join('}, {')+'} = 2 chains\n'+'width = min chain cover = 2  ✓  (Dilworth)';
  } else {
    const colorOf={}; rankLevels.forEach((lv,i)=>lv.forEach(n=>colorOf[n]=acColors[i]));
    const chainSet=new Set(longestChain);
    // highlight the chain edges
    for(let i=0;i+1<longestChain.length;i++){ const va=byN[longestChain[i]],vb=byN[longestChain[i+1]]; svg.appendChild(SVG('line',{x1:va.x,y1:va.y,x2:vb.x,y2:vb.y,stroke:'var(--ink)','stroke-width':3.5})); }
    for(const v of nodes){ drawNode(svg,v.x,v.y,v.n,{r:18,fill: chainSet.has(v.n)?'var(--panel)':'var(--panel2)', stroke: colorOf[v.n]||'var(--violet)', fontSize:13}); }
    const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent='bold edges = longest chain    node color = which rank-level antichain'; svg.appendChild(cap);
    msg='longest chain {'+longestChain.join(' | ')+'} has length 4 = HEIGHT\n'+'antichain (rank-level) cover: '+rankLevels.map(l=>'{'+l.join(',')+'}').join(', ')+' = 4 antichains\n'+'height = min antichain cover = 4  ✓  (Mirsky)';
  }
  out.textContent=msg;
}
viewSl.addEventListener('input',render);
render();

const svg=$('#sperner-svg'), out=$('#sperner-out');
const nSl=$('#sperner-n'), nL=$('#sperner-n-lbl');
const W=600,H=340;
function binom(n,k){ if(k<0||k>n) return 0; let r=1; for(let i=0;i<k;i++) r=r*(n-i)/(i+1); return Math.round(r); }
function render(){
  const n=+nSl.value; nL.textContent='n = '+n;
  svg.innerHTML='';
  const layers=[]; for(let k=0;k<=n;k++) layers.push(binom(n,k));
  const mid=Math.floor(n/2); const maxSize=binom(n,mid);
  const top=40, rowH=Math.min(40,(H-90)/(n+1)), cx=W/2;
  const maxBarW=W-160; const unit=maxBarW/maxSize;
  for(let k=0;k<=n;k++){ const y=top+(n-k)*rowH; const w=layers[k]*unit; const isMid=(k===mid);
    svg.appendChild(SVG('rect',{x:cx-w/2,y,width:Math.max(w,2),height:rowH-8,rx:5,
      fill: isMid?'var(--yellow)':'var(--violet)', opacity: isMid?0.95:0.6, stroke:'var(--line)'}));
    const lab=SVG('text',{x:cx-w/2-10,y:y+(rowH-8)/2+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); lab.textContent='|A|='+k; svg.appendChild(lab);
    const cnt=SVG('text',{x:cx+w/2+8,y:y+(rowH-8)/2+4,'font-size':11,fill: isMid?'var(--yellow)':'var(--mute)','font-weight':isMid?700:400}); cnt.textContent='C('+n+','+k+')='+layers[k]; svg.appendChild(cnt);
  }
  // LYM sum for the middle-layer antichain: maxSize * (1/maxSize) = 1
  const lymMid = maxSize * (1/binom(n,mid));
  out.textContent =
    'Boolean lattice B'+n+'    layer sizes: '+layers.join(', ')+'\n'+
    'middle layer |A| = '+mid+'  is the largest antichain, size  C('+n+','+mid+') = '+maxSize+'   (Sperner)\n'+
    'LYM check on the middle layer:  '+maxSize+' × 1/C('+n+','+mid+') = '+maxSize+'/'+binom(n,mid)+' = '+lymMid.toFixed(2)+'  ≤ 1  (tight)\n'+
    'every antichain in B'+n+' has at most '+maxSize+' sets; the LYM sum Σ 1/C(n,|A|) ≤ 1 forces it.';
}
nSl.addEventListener('input',render);
render();

const svg=$('#mobius-svg'), out=$('#mobius-out'), pick=$('#mobius-pick');
const W=600,H=340;
const POS={};
POS.b3={ name:'Boolean lattice B₃', bottom:'∅',
  nodes:[{id:'∅',x:300,y:300},{id:'a',x:150,y:210},{id:'b',x:300,y:210},{id:'c',x:450,y:210},{id:'ab',x:150,y:120},{id:'ac',x:300,y:120},{id:'bc',x:450,y:120},{id:'abc',x:300,y:35}],
  covers:[['∅','a'],['∅','b'],['∅','c'],['a','ab'],['a','ac'],['b','ab'],['b','bc'],['c','ac'],['c','bc'],['ab','abc'],['ac','abc'],['bc','abc']] };
POS.div30={ name:'divisor lattice of 30', bottom:'1',
  nodes:[{id:'1',x:300,y:300},{id:'2',x:150,y:210},{id:'3',x:300,y:210},{id:'5',x:450,y:210},{id:'6',x:150,y:120},{id:'10',x:300,y:120},{id:'15',x:450,y:120},{id:'30',x:300,y:35}],
  covers:[['1','2'],['1','3'],['1','5'],['2','6'],['2','10'],['3','6'],['3','15'],['5','10'],['5','15'],['6','30'],['10','30'],['15','30']] };
let cur='b3';
function reach(P){ const ids=P.nodes.map(n=>n.id); const leq={}; ids.forEach(i=>{leq[i]={}; ids.forEach(j=>leq[i][j]=(i===j));}); P.covers.forEach(([a,b])=>leq[a][b]=true); let ch=true; while(ch){ch=false; for(const x of ids) for(const y of ids) if(leq[x][y]) for(const z of ids) if(leq[y][z]&&!leq[x][z]){leq[x][z]=true;ch=true;}} return leq; }
function mobiusFrom(P,leq,x){ // mu(x,y) for all y>=x, by recursion
  const ids=P.nodes.map(n=>n.id).filter(y=>leq[x][y]);
  // order by interval size (number of z with x<=z<=y)
  ids.sort((p,q)=> ids.filter(z=>leq[x][z]&&leq[z][p]).length - ids.filter(z=>leq[x][z]&&leq[z][q]).length );
  const mu={};
  for(const y of ids){ if(y===x){ mu[y]=1; continue; } let s=0; for(const z of ids) if(z!==y && leq[x][z] && leq[z][y]) s+=mu[z]; mu[y]=-s; }
  return mu;
}
function render(){
  const P=POS[cur]; const leq=reach(P); const x=P.bottom; const mu=mobiusFrom(P,leq,x);
  svg.innerHTML='';
  const byId={}; P.nodes.forEach(n=>byId[n.id]=n);
  for(const [a,b] of P.covers){ const va=byId[a],vb=byId[b]; svg.appendChild(SVG('line',{x1:va.x,y1:va.y,x2:vb.x,y2:vb.y,stroke:'var(--line)','stroke-width':1.5,opacity:0.6})); }
  for(const n of P.nodes){ const m=mu[n.id]; const stroke = m===undefined?'var(--violet)':(m>0?'var(--cyan)':m<0?'var(--pink)':'var(--mute)');
    drawNode(svg,n.x,n.y,n.id,{r:18,fill:'var(--panel2)',stroke,fontSize:12});
    if(m!==undefined){ const t=SVG('text',{x:n.x+24,y:n.y+5,'font-size':12,fill:stroke,'font-weight':600}); t.textContent='μ='+m; svg.appendChild(t); } }
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent=P.name+'    μ('+x+', · )    cyan = +,  pink = −,  grey = 0'; svg.appendChild(cap);
  const ids=P.nodes.map(n=>n.id).filter(y=>leq[x][y]);
  const lines=ids.map(y=>'μ('+x+','+y+') = '+mu[y]);
  let extra = cur==='b3' ? 'on B₃ the values are (−1)^|set|, the inclusion–exclusion signs.' : 'on the divisor lattice μ(1,n) is the number-theoretic μ(n): −1 for one or three primes, +1 for two, 0 if not squarefree.';
  out.textContent = lines.join('   ') + '\n' + extra;
}
