const svg=$('#completeness-svg'), out=$('#completeness-out');
const mSl=$('#completeness-m'), mL=$('#completeness-m-lbl'), stepBtn=$('#completeness-step'), resetBtn=$('#completeness-reset');
const W=600,H=300;
let m=+mSl.value;
// f clamps k into [a,b]; monotone (non-decreasing). Every k in [a,b] is a fixed
// point, so the fixed-point set is the interval [a,b] — itself a complete
// sublattice with least element a and greatest element b (Knaster-Tarski).
function bounds(mm){ return { a: Math.max(1, Math.floor(mm/3)), b: Math.min(mm-1, Math.ceil(2*mm/3)) }; }
function f(k){ const bb=bounds(m); return Math.max(bb.a, Math.min(bb.b, k)); }
let cur=0, history=[0], done=false;
function reset(){ m=+mSl.value; cur=0; history=[0]; done=false; }
function step(){ if(done) return; const nx=f(cur); if(nx===cur){ done=true; return; } cur=nx; history.push(cur); if(cur===f(cur)) done=true; }
function render(){
  m=+mSl.value; mL.textContent='m = '+m;
  if(history.some(h=>h>m)) reset();
  svg.innerHTML='';
  const bb=bounds(m), a=bb.a, b=bb.b;
  const pad=60, span=W-2*pad; const y=150;
  for(let k=0;k<=m;k++){ const x=pad+span*k/Math.max(m,1);
    const isFixed=(k>=a && k<=b);
    let stroke='var(--violet)', fill='var(--panel2)';
    if(isFixed) stroke='var(--green)';
    if(k===cur){ stroke='var(--yellow)'; fill='var(--panel)'; }
    else if(history.includes(k)) stroke='var(--cyan)';
    drawNode(svg,x,y,k,{r:15,fill,stroke,fontSize:12});
    const fk=f(k), x2=pad+span*fk/Math.max(m,1);
    if(fk!==k) drawArrow(svg,[x,y-18],[x2,y-18],{color:'var(--mute)',curve:18,markerId:'cmp-arr',width:1});
  }
  const xa=pad+span*a/Math.max(m,1), xb=pad+span*b/Math.max(m,1);
  svg.appendChild(SVG('circle',{cx:xa,cy:y,r:22,fill:'none',stroke:'var(--green)','stroke-width':2.5}));
  svg.appendChild(SVG('circle',{cx:xb,cy:y,r:22,fill:'none',stroke:'var(--green)','stroke-width':2.5,'stroke-dasharray':'4 3'}));
  const cap=SVG('text',{x:20,y:28,'font-size':12,fill:'var(--mute)'}); cap.textContent='chain lattice {0,...,'+m+'}   arrows show f(k)   green = fixed points   solid ring = lfp, dashed = gfp'; svg.appendChild(cap);
  const la=SVG('text',{x:xa,y:y+44,'text-anchor':'middle','font-size':12,fill:'var(--green)'}); la.textContent='lfp = '+a; svg.appendChild(la);
  const lb=SVG('text',{x:xb,y:y+44,'text-anchor':'middle','font-size':12,fill:'var(--green)'}); lb.textContent='gfp = '+b; svg.appendChild(lb);
  out.textContent =
    'monotone map f on the complete lattice {0,...,'+m+'}:  f(k) = clamp(k, '+a+', '+b+')\n'+
    'iterating from the bottom 0:  '+history.join(' -> ')+(done?'  (stabilized at the lfp)':'  (press step)')+'\n'+
    'fixed points = the whole interval ['+a+', '+b+'] — a sublattice with least '+a+' (lfp, reached from the bottom) and greatest '+b+' (gfp, reached from the top '+m+')\n'+
    'Knaster-Tarski: monotonicity alone — no metric, no contraction — makes the fixed-point set a nonempty complete lattice.';
}
mSl.addEventListener('input',()=>{ reset(); render(); });
stepBtn.addEventListener('click',()=>{ step(); render(); });
resetBtn.addEventListener('click',()=>{ reset(); render(); });
reset(); render();
